{"cmd": "cat > /mnt/c/anvil/wk01/bench/karlo10/internal/api/v1/gate_evaluations_test.go << 'EOF'
package v1

import (
	"net/http"
	"testing"

	"github.com/luwa07832/deployment-tracker/internal/store"
)

const gateCheckBody = `{"checks":[
  {"check_name":"canary","status":"passed","evidence":"canary metrics stable"},
  {"check_name":"security-scan","status":"waived","evidence":"scan run 42","waiver_reason":"accepted residual risk"}
]}`

const gateFailedBody = `{"checks":[
  {"check_name":"canary","status":"failed","evidence":"error rate above threshold"},
  {"check_name":"smoke","status":"pending","evidence":"queued behind deploy"}
]}`

// recordWithGate creates a release record with the given gate status and
// returns its public id.
func recordWithGate(t *testing.T, router httpHandler, environment, version, gate string) string {
	t.Helper()
	body := `{"environment":"` + environment + `","version":"` + version + `","changes":[
	  {"category":"feature","title":"c","description":"d"}],
	  "gate_status":"` + gate + `","rollback_point":"snap:base"}`
	record := createRecordOK(t, router.(*ginEngineShim).engine, body)
	return record["id"].(string)
}

func TestCreateGateEvaluationReturnsSnapshot(t *testing.T) {
	router := newTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	id := recordWithGate(t, router, "prod", "1.2.0", "allowed")

	recorder := doRequest(t, router, http.MethodPost,
		"/api/v1/release-records/"+id+"/gate-evaluations", gateCheckBody)
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200 (body %s)", recorder.Code, recorder.Body.String())
	}
	evaluation := decodeBody(t, recorder)["gate_evaluation"].(map[string]any)
	if evaluation["release"] != id {
		t.Fatalf("release = %v, want %s", evaluation["release"], id)
	}
	if evaluation["environment"] != "prod" || evaluation["version"] != "1.2.0" {
		t.Fatalf("locator fields = %v", evaluation)
	}
	if evaluation["gate_status"] != "allowed" || evaluation["effective_gate_status"] != "allowed" {
		t.Fatalf("gate fields = %v", evaluation)
	}
	checks := evaluation["checks"].([]any)
	if len(checks) != 2 {
		t.Fatalf("checks = %v", checks)
	}
	// Sorted by check_name: canary before security-scan even though the
	// submission order was the same here.
	first := checks[0].(map[string]any)
	if first["check_name"] != "canary" || first["status"] != "passed" ||
		first["evidence"] != "canary metrics stable" {
		t.Fatalf("first check = %v", first)
	}
	if _, present := first["waiver_reason"]; present {
		t.Fatalf("waiver_reason must be omitted for non-waived checks: %v", first)
	}
	second := checks[1].(map[string]any)
	if second["check_name"] != "security-scan" || second["waiver_reason"] != "accepted residual risk" {
		t.Fatalf("second check = %v", second)
	}
}

func TestCreateGateEvaluationIdempotentAndConflict(t *testing.T) {
	router := newTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	id := recordWithGate(t, router, "prod", "1.2.0", "allowed")
	path := "/api/v1/release-records/" + id + "/gate-evaluations"

	first := doRequest(t, router, http.MethodPost, path, gateCheckBody)
	if first.Code != http.StatusOK {
		t.Fatalf("first = %d %s", first.Code, first.Body.String())
	}
	// Same content, checks in reverse order: still the same snapshot, 200.
	reordered := `{"checks":[
	  {"check_name":"security-scan","status":"waived","evidence":"scan run 42","waiver_reason":"accepted residual risk"},
	  {"check_name":"canary","status":"passed","evidence":"canary metrics stable"}
	]}`
	second := doRequest(t, router, http.MethodPost, path, reordered)
	if second.Code != http.StatusOK {
		t.Fatalf("identical resubmission = %d %s", second.Code, second.Body.String())
	}
	if second.Body.String() != first.Body.String() {
		t.Fatalf("identical resubmission body differs:\n%s\nvs\n%s", second.Body.String(), first.Body.String())
	}

	different := `{"checks":[
	  {"check_name":"canary","status":"passed","evidence":"different evidence"}
	]}`
	conflict := doRequest(t, router, http.MethodPost, path, different)
	wantError(t, conflict, http.StatusConflict, store.CodeGateEvaluationConflictV1)

	// Different checks that would derive another status answer MISMATCH.
	mismatch := doRequest(t, router, http.MethodPost, path, gateFailedBody)
	wantError(t, mismatch, http.StatusConflict, store.CodeGateStatusMismatchV1)
}

func TestCreateGateEvaluationStatusDerivation(t *testing.T) {
	cases := []struct {
		name       string
		recordGate string
		body       string
	}{
		{"failed dominates", "blocked", gateFailedBody},
		{"pending", "pending", `{"checks":[{"check_name":"s","status":"pending","evidence":"e"}]}`},
		{"allowed", "allowed", `{"checks":[{"check_name":"s","status":"passed","evidence":"e"}]}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			router := newTestRouter(t)
			registerEnvironmentOK(t, router, "prod")
			id := recordWithGate(t, router, "prod", "9.9.9", tc.recordGate)
			recorder := doRequest(t, router, http.MethodPost,
				"/api/v1/release-records/"+id+"/gate-evaluations", tc.body)
			if recorder.Code != http.StatusOK {
				t.Fatalf("status = %d body %s", recorder.Code, recorder.Body.String())
			}
			evaluation := decodeBody(t, recorder)["gate_evaluation"].(map[string]any)
			if evaluation["effective_gate_status"] != tc.recordGate {
				t.Fatalf("effective = %v, want %s", evaluation["effective_gate_status"], tc.recordGate)
			}
		})
	}
}

func TestCreateGateEvaluationMismatchAndNotFound(t *testing.T) {
	router := newTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	allowedID := recordWithGate(t, router, "prod", "1.0.0", "allowed")

	recorder := doRequest(t, router, http.MethodPost,
		"/api/v1/release-records/"+allowedID+"/gate-evaluations", gateFailedBody)
	wantError(t, recorder, http.StatusConflict, store.CodeGateStatusMismatchV1)

	missing := doRequest(t, router, http.MethodPost,
		"/api/v1/release-records/rel_missing/gate-evaluations", gateCheckBody)
	wantError(t, missing, http.StatusNotFound, store.CodeReleaseRecordNotFoundV1)
}

func TestCreateGateEvaluationInvalidBodies(t *testing.T) {
	router := newTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	id := recordWithGate(t, router, "prod", "1.0.0", "allowed")
	path := "/api/v1/release-records/" + id + "/gate-evaluations"

	badJSON := doRequest(t, router, http.MethodPost, path, `{"checks":`)
	wantError(t, badJSON, http.StatusBadRequest, store.CodeInvalidRequest)

	bodies := []string{
		`{}`,
		`{"checks":[]}`,
		`{"checks":[{"status":"passed","evidence":"e"}]}`,
		`{"checks":[{"check_name":"  ","status":"passed","evidence":"e"}]}`,
		`{"checks":[{"check_name":"a","status":"passed","evidence":"e"},
		           {"check_name":"a","status":"failed","evidence":"e2"}]}`,
		`{"checks":[{"check_name":"a","status":"unknown","evidence":"e"}]}`,
		`{"checks":[{"check_name":"a","status":"passed","evidence":"   "}]}`,
		`{"checks":[{"check_name":"a","status":"waived","evidence":"e"}]}`,
		`{"checks":[{"check_name":"a","status":"passed","evidence":"e","waiver_reason":"x"}]}`,
		`{"checks":[{"check_name":"a","status":"waived","evidence":"e","waiver_reason":"  "}]}`,
	}
	for _, body := range bodies {
		recorder := doRequest(t, router, http.MethodPost, path, body)
		wantError(t, recorder, http.StatusUnprocessableEntity, store.CodeGateEvaluationValidationV1)
	}

	wrongType := doRequest(t, router, http.MethodPost, path,
		`{"checks":[{"check_name":"a","status":7,"evidence":"e"}]}`)
	wantError(t, wrongType, http.StatusUnprocessableEntity, store.CodeGateEvaluationValidationV1)
}

func TestGetGateEvaluation(t *testing.T) {
	router := newTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	id := recordWithGate(t, router, "prod", "1.2.0", "allowed")
	path := "/api/v1/release-records/" + id + "/gate-evaluations"

	wantError(t, doRequest(t, router, http.MethodGet, path, ""),
		http.StatusNotFound, store.CodeGateEvaluationNotFoundV1)

	if r := doRequest(t, router, http.MethodPost, path, gateCheckBody); r.Code != http.StatusOK {
		t.Fatalf("create: %s", r.Body.String())
	}
	recorder := doRequest(t, router, http.MethodGet, path, "")
	if recorder.Code != http.StatusOK {
		t.Fatalf("get = %d %s", recorder.Code, recorder.Body.String())
	}
	evaluation := decodeBody(t, recorder)["gate_evaluation"].(map[string]any)
	if evaluation["release"] != id || evaluation["gate_status"] != "allowed" {
		t.Fatalf("evaluation = %v", evaluation)
	}
	checks := evaluation["checks"].([]any)
	if len(checks) != 2 || checks[0].(map[string]any)["check_name"] != "canary" {
		t.Fatalf("checks = %v", checks)
	}

	wantError(t, doRequest(t, router, http.MethodGet,
		"/api/v1/release-records/rel_missing/gate-evaluations", ""),
		http.StatusNotFound, store.CodeGateEvaluationNotFoundV1)
}

func TestListGateEvaluations(t *testing.T) {
	router := newTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	registerEnvironmentOK(t, router, "staging")
	prodAllowed := recordWithGate(t, router, "prod", "1.0.0", "allowed")
	prodBlocked := recordWithGate(t, router, "prod", "1.1.0", "blocked")
	stagingPending := recordWithGate(t, router, "staging", "1.0.0", "pending")
	post := func(id, body string) {
		t.Helper()
		r := doRequest(t, router, http.MethodPost,
			"/api/v1/release-records/"+id+"/gate-evaluations", body)
		if r.Code != http.StatusOK {
			t.Fatalf("post %s: %s", id, r.Body.String())
		}
	}
	post(prodAllowed, gateCheckBody)
	post(prodBlocked, gateFailedBody)
	post(stagingPending, `{"checks":[{"check_name":"waiting","status":"pending","evidence":"queued"}]}`)

	recorder := doRequest(t, router, http.MethodGet, "/api/v1/gate-evaluations", "")
	if recorder.Code != http.StatusOK {
		t.Fatalf("list = %d %s", recorder.Code, recorder.Body.String())
	}
	body := decodeBody(t, recorder)
	items := body["gate_evaluations"].([]any)
	if len(items) != 3 {
		t.Fatalf("items = %v", items)
	}
	// Newest first follows snapshot insertion order.
	versions := []string{
		items[0].(map[string]any)["version"].(string),
		items[1].(map[string]any)["version"].(string),
		items[2].(map[string]any)["version"].(string),
	}
	if versions[0] != "1.0.0" || versions[1] != "1.1.0" || versions[2] != "1.0.0" {
		t.Fatalf("versions newest first = %v", versions)
	}
