	if empty.Code != http.StatusOK {
		t.Fatalf("empty list status = %d", empty.Code)
	}
	body := decodeBody(t, empty)
	if items, _ := body["gate_evaluations"].([]any); len(items) != 0 {
		t.Fatalf("empty list must be a definite []: %v", body)
	}
